package com.hostel.hostelmanagement.entity; import com.hostel.hostelmanagement.enums.Role; import jakarta.persistence.*; @Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String name; @Column(nullable=false,unique=true) String email; @Column(nullable=false) String password; @Enumerated(EnumType.STRING) Role role; String phone,department,studentId; public User(){} public User(String n,String e,String p,Role r){name=n;email=e;password=p;role=r;} public Long getId(){return id;} public String getName(){return name;} public String getEmail(){return email;} public String getPassword(){return password;} public Role getRole(){return role;} public String getPhone(){return phone;} public String getDepartment(){return department;} public String getStudentId(){return studentId;} public void setId(Long v){id=v;} public void setName(String v){name=v;} public void setEmail(String v){email=v;} public void setPassword(String v){password=v;} public void setRole(Role v){role=v;} public void setPhone(String v){phone=v;} public void setDepartment(String v){department=v;} public void setStudentId(String v){studentId=v;} }